package main

import (
	"fmt"

	"goa.design/goa/v3/eval"
	"goa.design/goa/v3/expr"
	. "goa.design/goa/v3/dsl"
)

func main() {
	fmt.Println("=== Example: Using Deprecated() in DSL ===\n")

	// Initialize
	expr.Root = &expr.RootExpr{}
	eval.Context = &eval.DSLContext{}

	// Define API
	var _ = API("my-api", func() {
		Title("My API")
		Description("An API with deprecated endpoints")
	})

	// Define service with both deprecated and active methods
	var _ = Service("user-service", func() {
		Description("User management service")

		// Deprecated method
		Method("get-user-legacy", func() {
			Description("Legacy method to get user - use get-user instead")
			HTTP(func() {
				GET("/users/legacy/{id}")
				Deprecated() // Marks this endpoint as deprecated in OpenAPI
			})
		})

		// Active method
		Method("get-user", func() {
			Description("Get user by ID")
			HTTP(func() {
				GET("/users/{id}")
				// No Deprecated() call - this endpoint is active
			})
		})
	})

	if eval.Context.Errors != nil {
		fmt.Printf("ERROR: %s\n", eval.Context.Errors)
		return
	}

	// Verify the design
	http := expr.Root.API.HTTP
	if http == nil || len(http.Services) == 0 {
		fmt.Println("ERROR: No HTTP services found")
		return
	}

	svc := http.Services[0]
	fmt.Printf("Service: %s\n", svc.Name())
	fmt.Printf("Number of endpoints: %d\n\n", len(svc.HTTPEndpoints))

	for i, ep := range svc.HTTPEndpoints {
		fmt.Printf("Endpoint %d: %s\n", i+1, ep.Name())

		// Check if deprecated
		if v, ok := ep.Meta.Last("openapi:deprecated"); ok && v == "true" {
			fmt.Printf("  Status: DEPRECATED ✓\n")
		} else {
			fmt.Printf("  Status: ACTIVE\n")
		}

		// Show routes
		for j, route := range ep.Routes {
			fmt.Printf("  Route %d: %s %s\n", j+1, route.Method, route.Path)
		}
		fmt.Println()
	}

	fmt.Println("=== Example Complete ===")
	fmt.Println("\nThe Deprecated() function successfully marks endpoints as deprecated.")
	fmt.Println("When generating OpenAPI specs, these endpoints will have deprecated=true.")
}
EOF
